export * as Message from './message.tsx';
export type {
  ErrorProps as MessageErrorProps,
  MessageFrom,
  MessageStatus,
  RootOwnProps as MessageRootOwnProps,
  RootProps as MessageRootProps,
} from './message.tsx';

@layer hj.components {
  /*
   * Customise: --hj-message-bubble-bg · --hj-message-bubble-max · --hj-message-gap
   */
  .hj-message {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    column-gap: calc(12px * var(--hj-density));
    row-gap: calc(4px * var(--hj-density));
    align-items: start;
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    animation: hj-message-in var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle) both;
  }
  .hj-message > :not(.hj-message-avatar) {
    grid-column: 2;
  }
  .hj-message:not(:has(> .hj-message-avatar)) {
    grid-template-columns: minmax(0, 1fr);
  }
  .hj-message:not(:has(> .hj-message-avatar)) > * {
    grid-column: 1;
  }
  /* A new turn rises a short way and fades in — once, on arrival. */
  @keyframes hj-message-in {
    from {
      opacity: 0;
      transform: translateY(calc(var(--hj-rise) * var(--hj-travel)));
    }
  }

  .hj-message-avatar {
    grid-row: 1 / span 4;
    display: grid;
    place-items: center;
    width: 28px;
    height: 28px;
    margin-top: 1px;
    overflow: hidden;
    border-radius: var(--hj-radius-pill);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg-dim);
    font-size: 15px;
    font-weight: 600;
    line-height: 0;
  }
  .hj-message-avatar svg {
    width: 16px;
    height: 16px;
  }
  .hj-message-author {
    display: flex;
    align-items: baseline;
    gap: calc(8px * var(--hj-density));
    font-size: 13px;
    font-weight: 600;
    line-height: 28px;
    color: var(--hj-fg);
  }
  .hj-message-author time,
  .hj-message-author small {
    font-weight: 400;
    font-size: 12px;
    color: var(--hj-fg-mute);
    font-variant-numeric: tabular-nums;
  }

  .hj-message-content {
    min-width: 0;
    font-size: 15px;
    line-height: 1.6;
    overflow-wrap: anywhere;
  }
  .hj-message-content > :first-child {
    margin-top: 0;
  }
  .hj-message-content > :last-child {
    margin-bottom: 0;
  }

  /* The person's turn: a bubble, on the right, on surface. */
  .hj-message[data-from='user'] {
    grid-template-columns: minmax(0, 1fr);
    justify-items: end;
  }
  .hj-message[data-from='user'] > * {
    grid-column: 1;
  }
  .hj-message[data-from='user'] .hj-message-avatar {
    display: none;
  }
  .hj-message[data-from='user'] .hj-message-content {
    max-width: var(--hj-message-bubble-max, min(80%, 560px));
    padding: calc(10px * var(--hj-density)) calc(16px * var(--hj-density));
    border-radius: var(--hj-radius-lg) var(--hj-radius-lg) var(--hj-radius-xs) var(--hj-radius-lg);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-message-bubble-bg, var(--hj-surface));
    box-shadow: inset 0 0 0 1px var(--hj-line);
  }

  /* System notes: centred, quiet, no avatar. */
  .hj-message[data-from='system'] {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    text-align: center;
  }
  .hj-message[data-from='system'] > * {
    grid-column: 1;
  }
  .hj-message[data-from='system'] .hj-message-avatar {
    display: none;
  }
  .hj-message[data-from='system'] .hj-message-content {
    font-size: 12.5px;
    line-height: 17px;
    color: var(--hj-fg-mute);
  }

  .hj-message[data-status='error'] .hj-message-content {
    color: var(--hj-fg-dim);
  }

  .hj-message-footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: calc(8px * var(--hj-density));
    min-height: calc(32px * var(--hj-density-size));
    font-size: 12px;
    color: var(--hj-fg-mute);
  }
  .hj-message[data-from='user'] .hj-message-footer {
    justify-content: flex-end;
  }

  .hj-message-error {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: calc(6px * var(--hj-density)) calc(10px * var(--hj-density));
    padding: calc(10px * var(--hj-density)) calc(12px * var(--hj-density));
    border-radius: var(--hj-radius-sm);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-danger-soft);
    color: var(--hj-danger);
    font-size: 13.5px;
    line-height: 1.45;
  }
  .hj-message-error-glyph {
    display: inline-flex;
    flex: none;
    line-height: 0;
  }
  .hj-message-error-glyph svg {
    width: 16px;
    height: 16px;
  }
  .hj-message-error-text {
    flex: 1;
    min-width: 12ch;
    color: var(--hj-fg);
  }
  .hj-message-error-action {
    display: inline-flex;
    margin-left: auto;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart } from '../../system/part.tsx';
import type { ElementPartProps } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

export type MessageFrom = 'user' | 'assistant' | 'system';
export type MessageStatus = 'complete' | 'streaming' | 'error';

/** Props hanji adds to the message row. */
export interface RootOwnProps {
  /** Who wrote it. user = bubble on the right · assistant = flush on the paper · system = a quiet centred note. */
  from?: MessageFrom;
  /** complete · streaming (still arriving) · error (failed; show Message.Error with a retry). */
  status?: MessageStatus;
}
export interface RootProps extends RootOwnProps, Omit<React.ComponentProps<'div'>, 'className'> {
  className?: string;
  render?: useRender.RenderProp;
}

/**
 * One turn in a conversation.
 *
 * @example
 * <Message.Root from="assistant">
 *   <Message.Avatar>…</Message.Avatar>
 *   <Message.Content>…</Message.Content>
 *   <Message.Footer><MessageActions.Root>…</MessageActions.Root></Message.Footer>
 * </Message.Root>
 */
export function Root(props: RootProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    from = 'assistant',
    status = 'complete',
    className,
    render,
    ...rest
  } = withDefaults(config, 'Message.Root', props);
  return useRender({
    render,
    defaultTagName: 'div',
    props: {
      ...rest,
      'data-from': from,
      'data-status': status,
      'data-streaming': flag(status === 'streaming'),
      'aria-busy': status === 'streaming' || undefined,
      className: cls(config, 'Message.Root', 'hj-message', className) as string | undefined,
    },
  });
}

/** 28px slot for an avatar or the assistant's mark. Decorative: name the author in Author. */
export const Avatar: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Message.Avatar',
  'hj-message-avatar',
);
/** The author line above the content (model name, person, time). */
export const Author: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Message.Author',
  'hj-message-author',
);
/** The body. A bubble for the user; flush text for the assistant. */
export const Content: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Message.Content',
  'hj-message-content',
);
/** Under the content: time, MessageActions, attachments, sources. */
export const Footer: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Message.Footer',
  'hj-message-footer',
);

export interface ErrorOwnProps {
  /** A retry button or link, placed after the sentence. */
  action?: React.ReactNode;
}
export interface ErrorProps extends ErrorOwnProps, React.ComponentProps<'div'> {}

/** A failed or refused reply: glyph + sentence + an optional retry. role="alert". */
export function Error(props: ErrorProps): React.ReactElement {
  const config = useHanjiConfig();
  const { action, className, children, ...rest } = withDefaults(config, 'Message.Error', props);
  const styled = !config.unstyled;
  return (
    <div
      role="alert"
      {...rest}
      className={cls(config, 'Message.Error', 'hj-message-error', className) as string | undefined}
    >
      <span className={styled ? 'hj-message-error-glyph' : undefined} aria-hidden="true">
        {config.icons.alert}
      </span>
      <span className={styled ? 'hj-message-error-text' : undefined}>{children}</span>
      {action ? (
        <span className={styled ? 'hj-message-error-action' : undefined}>{action}</span>
      ) : null}
    </div>
  );
}
